argv:
query=query($owner: String!, $repo: String!, $p0: Int!, $p1: Int!) {
  repository(owner: $owner, name: $repo) {
    p0: pullRequest(number: $p0) { number url state mergedAt timelineItems(last: 1, itemTypes: [CLOSED_EVENT]) { nodes { ... on ClosedEvent { actor { login } } } } }
    p1: pullRequest(number: $p1) { number url state mergedAt timelineItems(last: 1, itemTypes: [CLOSED_EVENT]) { nodes { ... on ClosedEvent { actor { login } } } } }
  }
}
